458:     dom.btnBuild.disabled = true;
459:     dom.validationInline.classList.remove('show');
460:     setValidation('error', 'CIRCUIT INCOMPLETE', 'Draw one continuous loop to unlock the build.');
461:     return;
462:   }
463: 
464:   dom.statLength.textContent = preview.length.toLocaleString();
465:   dom.statTurns.textContent = preview.turns;
466:   dom.statStraight.textContent = preview.longestStraight.toLocaleString();
467:   dom.readoutLength.textContent = `${preview.length.toLocaleString()} m`;
468:   dom.readoutTurns.textContent = `${preview.turns} turns`;
469: 
470:   if (preview.selfIntersects) {
471:     dom.drawStatus.textContent = 'SELF-INTERSECTION DETECTED';
472:     dom.btnBuild.disabled = true;
473:     setValidation('error', 'TRACK CROSSES ITSELF', 'Erase and redraw one clean loop. Bridges arrive in APEX INK 2.');
474:     dom.validationInline.textContent = 'FIX THE CROSSING';
475:     dom.validationInline.classList.add('show');
476:   } else if (preview.tooFew) {
477:     dom.drawStatus.textContent = 'KEEP DRAWING';
478:     dom.btnBuild.disabled = true;
479:     setValidation('error', 'THAT IS A SCRIBBLE', 'Hold and drag to sketch a full circuit — bigger than a dot.');
480:     dom.validationInline.textContent = 'LOOP TOO SHORT';
481:     dom.validationInline.classList.add('show');
482:   } else if (preview.tooSmall) {
483:     dom.drawStatus.textContent = 'DRAW BIGGER';
