1878: function trackDistanceAt(track, index, x, z) {
1879:   const s = track.samples[index];
1880:   const along = (x - s.x) * s.tx + (z - s.z) * s.tz;
1881:   return (s.s ?? index * track.step) + clamp(along, -track.step, track.step);
1882: }
