1884: function unwrapTrackDistance(candidate, reference, length) {
1885:   let out = candidate;
1886:   const half = length * 0.5;
1887:   while (out - reference > half) out -= length;
1888:   while (out - reference < -half) out += length;
1889:   return out;
1890: }
