.race-message.is-final { color: var(--orange); }

/* Team-radio pit call, pinned under the top HUD so it never covers the timing. */
.pit-call {
  position: absolute; left: 50%; top: 96px; z-index: 6;
  width: min(430px, calc(100vw - 32px));
  transform: translate(-50%, -16px) scale(.97);
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 10px 18px 12px;
  color: var(--cream); text-align: center; pointer-events: none;
  background: linear-gradient(180deg, rgba(15,17,22,.96), rgba(8,10,14,.9));
  border: 1px solid rgba(255,77,31,.5); border-top: 3px solid var(--orange);
  box-shadow: 0 14px 46px rgba(0,0,0,.55), 0 0 38px rgba(255,77,31,.12);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 13px), calc(100% - 13px) 100%, 0 100%);
  opacity: 0; visibility: hidden;
  transition: opacity .22s, transform .22s var(--ease), visibility .22s;
}
.pit-call.show { opacity: 1; visibility: visible; transform: translate(-50%, 0) scale(1); }
.pit-call.is-service { border-color: rgba(255,211,106,.6); border-top-color: #ffd36a; }
.pit-call.is-done { border-color: rgba(182,255,92,.55); border-top-color: var(--good); }
.pit-call-radio {
  display: flex; align-items: center; gap: 6px;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: .26em; color: #ffd36a;
}
.pit-call-radio i { width: 5px; height: 5px; border-radius: 50%; background: #ffd36a; box-shadow: 0 0 8px #ffd36a; animation: radioblip .9s infinite; }
.pit-call-radio em { margin-left: auto; font-style: normal; color: var(--dim); letter-spacing: .16em; }
.pit-call strong {
  font-family: var(--font-display); font-weight: 700; font-size: clamp(30px, 4.2vw, 48px);
  line-height: .98; letter-spacing: .055em; text-transform: uppercase;
  text-shadow: 0 0 32px rgba(255,77,31,.3);
}
.pit-call small { font-family: var(--font-mono); font-size: 8px; letter-spacing: .18em; color: #c9c3b5; }
.pit-call-progress { width: 100%; height: 3px; margin-top: 7px; background: rgba(255,255,255,.1); overflow: hidden; opacity: 0; }
.pit-call.is-service .pit-call-progress { opacity: 1; }
.pit-call-progress span { display: block; width: 0%; height: 100%; background: linear-gradient(90deg, #ffd36a, var(--orange)); transition: width .12s linear; }
@keyframes radioblip { 0%, 100% { opacity: 1; } 50% { opacity: .25; } }
.tyre-chip { color: #d8d2c3; border: 1px solid rgba(255,255,255,.16); padding: 2px 5px; white-space: nowrap; }
.tyre-chip.is-fresh { color: var(--good); border-color: rgba(182,255,92,.35); }
.tyre-chip.is-worn { color: #ffc36b; border-color: rgba(255,195,107,.42); }

