import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { createRequire } from 'node:module';
const runtime = process.env.OMGITHUB_PLAYWRIGHT_DIR || join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
if (!process.env.DISPLAY) { try { process.env.DISPLAY = `:${readFileSync(join(runtime, 'display'), 'utf8').trim()}`; } catch {} }
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
launchOptions.executablePath = '/opt/google/chrome/chrome';
const browser = await chromium.launch(launchOptions);
const ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, screen: { width: 390, height: 844 }, deviceScaleFactor: 1, isMobile: true, hasTouch: true });
const page = await ctx.newPage();
page.on('pageerror', e => console.log('[pageerror]', e.message));
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex, null, { timeout: 30000 });
await page.waitForTimeout(800);
const info = await page.evaluate(async () => {
  const a = window.__apex;
  document.querySelector('#setup-laps').value = '3';
  await a.beginBuild(a.demoPoints(0), { instant: true });
  a.startRaceNow();
  const race = a.race;
  for (let i = 0; i < 60 * 300; i++) {
    const p = race.player;
    const L = race.track.length;
    const s = ((p.progressDist % L) + L) % L;
    const idx = Math.floor(((s + 18) % L) / race.track.step) % race.track.N;
    const t = race.track.samples[idx];
    let err = Math.atan2(t.x - p.pos.x, t.z - p.pos.z) - p.yaw;
    while (err > Math.PI) err -= Math.PI * 2;
    while (err < -Math.PI) err += Math.PI * 2;
    a.setDemoInput({ left: err > 0.025, right: err < -0.025 });
    a.tick(1 / 60);
    if (race.pit.phase === 'called') break;
  }
  return { lap: race.player.lapsCompleted + 1, phase: race.pit.phase, line: race.pit.callLine };
});
console.log(info);
await page.waitForTimeout(250);
await page.screenshot({ path: '/tmp/opencode/shots/pit-mobile.jpg', type: 'jpeg', quality: 80 });
await browser.close();

